{% macro fidelity_raw_actvyd_activity(src) -%}
select
    trim(substring(content, 2, 3)) || trim(substring(content, 5, 6))                      as ACCOUNT_CUSTODIAL
  , trim(substring(content, 2, 3)) || '-' || trim(substring(content, 5, 6))               as ACCOUNT_CUSTODIAL_FORMATTED
