  , nullif(trim(substring(content, 2, 3)), '')                                            as BRANCH
  , nullif(trim(substring(content, 5, 6)), '')                                            as ACCOUNT_NUMBER
  , nullif(trim(substring(content, 11, 1)), '')                                           as ACCOUNT_TYPE
  , nullif(trim(substring(content, 12, 9)), '')                                           as CUSIP
  , nullif(trim(substring(content, 21, 2)), '')                                           as KEY_CODE
